""" This is used to find the range of a set of data. The range is the difference between the lowest and highest valued digits in a given set of data."""
def dataRange(data: Any) -> object {
    data = data;
    data.sort();
    return (data[(len(data) - 1)] - data[0]);
}

"""
    Converts string representations of architecutre
    sampling methodology to the dictionary format
    that nas_searchmanager.SearchManager uses.

    Example:
    \"1:4,2:4,3:4,4:4\" is converted to
    {1.0 : 4, 2.0 : 4, 3.0 : 4, 4.0 : 4}.
    """
def arch_sampling_str_to_dict(sampling_str: Any) -> object {
    sampling_str = sampling_str.replace(" ", "");
    archs_sampled_list = sampling_str.split(",");
    arch_sampling_dict = {};
    for curr_arch_sampling in archs_sampled_list {
        [num_epochs_elapsed, num_archs_to_sample] = curr_arch_sampling.split(":");
        arch_sampling_dict[float(num_epochs_elapsed)] = int(num_archs_to_sample);
    }
    return arch_sampling_dict;
}

"""
    From the full url path, this prunes it to just the query section,
    that starts with 'q=' and ends either at the end of the line of the
    next found '&'.

    Parameters
    ----------
    url_path : str
        The full url of the request to chop up

    Returns
    -------
    str
        The pruned query string, with any other replaced string
    """
def get_search_params(url_path: Any) -> object {
    query_params = url_path[len('/search.json?'):];
    queryPos = query_params.find('q=');
    if (queryPos == -1) {
        return [];
    }
    query_params = query_params[(queryPos + 2):];
    endPos = query_params.find('&');
    if (endPos != -1) {
        query_params = query_params[:endPos];
    }
    return query_params;
}

"""Returns the index of the closing bracket that matches the first opening bracket.
       Returns -1 if no last matching bracket is found, i.e. not a template.

       Example:
         'Foo<T>::iterator<U>''
         returns 5
    """
def find_match_brackets(search: Any, opening: Any = '<', closing: Any = '>') -> object {
    index = search.find(opening);
    if (index == -1) {
        return -1;
    }
    start = index + 1;
    count = 1;
    str_len = len(search);
    for index in range(start, str_len) {
        c = search[index];
        if (c == opening) {
            count += 1;
        } elif (c == closing) {
            count -= 1;
        }
        if (count == 0) {
            return index;
        }
    }
    return -1;
}

""" Return the number of words in the given text. """
def wordcount(text: Any) -> object {
    if (`type(text) == str) {
        return len(text.split(" "));
    } elif (`type(text) == `list) {
        return len(text);
    } else {
        raise ValueError(
            "Text to count words for must be of type str or of type list."
        );
    }
}

